import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(9))
G.add_edges_from([(5,7), (1,5), (3,6), (5,6), (4,5), (4,6), (0,7)])
while min(deg for node, deg in G.degree()) < 5:
    for u in range(9):
        for v in range(u+1, 9):
            if not G.has_edge(u, v):
                G.add_edge(u, v)
                if min(deg for node, deg in G.degree()) >= 5:
                    break
        else:
            continue
        break
print([(u, v) for u, v in G.edges() if u < v])
